/**
 *  Test case method for ODE-958
 * @throws Exception
 */
@Test(dataProvider = "configs")
public void testActivateRetiredProcess() throws Exception {
    String bundleName = "TestInstanceRetire";
    System.out.println("=> " + server.getODEServer().getProcessStore().getPackages());
    if (server.isDeployed("1"))
        server.undeployProcess(bundleName + "/1");
    if (server.isDeployed("2"))
        server.undeployProcess(bundleName + "/2");
    QName pid1 = server.deployProcess(bundleName + "/1").iterator().next();
    server.getODEServer().getProcessManagement().setPackageRetired("1", true);
    QName pid2 = server.deployProcess(bundleName + "/2").iterator().next();
    try {
        server.getODEServer().getProcessManagement().setPackageRetired("1", false);
    } catch (ContextException e) {
    }
    TProcessInfo pInfo = getProcessDetails(pid1);
    assertTrue(ProcessState.RETIRED.name().equals(pInfo.getStatus().toString()));
    if (server.isDeployed("1"))
        server.undeployProcess(bundleName + "/1");
    if (server.isDeployed("2"))
        server.undeployProcess(bundleName + "/2");
}

@Test
public void testDeployUndeploy() throws Exception {
    // Setup and tear down are doing ost of the job here, just checking in the middle
    // Check deployment
    OMElement listRoot = _client.buildMessage("listProcesses", new String[] { "filter", "orderKeys" }, new String[] { "", "" });
    OMElement result = sendToPM(listRoot);
    // look for DynPartnerMain-xxx
    listRoot = _client.buildMessage("listProcesses", new String[] { "filter", "orderKeys" }, new String[] { "name=" + _deployed.get(0).getLocalPart(), "" });
    result = sendToPM(listRoot);
    result = result.getFirstElement();
    assertEquals("process-info-list", result.getLocalName());
    OMElement child = result.getFirstElement();
    assertNotNull("Missing deployed process", child);
    assertEquals("process-info", child.getLocalName());
    OMElement pid = child.getFirstElement();
    assertEquals(_deployed.get(0).toString(), pid.getText());
    // look for DynPartnerResponder-xxx
    listRoot = _client.buildMessage("listProcesses", new String[] { "filter", "orderKeys" }, new String[] { "name=" + _deployed.get(1).getLocalPart(), "" });
    result = sendToPM(listRoot);
    result = result.getFirstElement();
    assertEquals("process-info-list", result.getLocalName());
    child = result.getFirstElement();
